int findCircleNum(vector<vector<int>>& a) {
    int n = a.size(), comps = n; vector<int> p(n); iota(p.begin(), p.end(), 0);
    function<int(int)> f = [&](int x) { while (p[x] != x) { p[x] = p[p[x]]; x = p[x]; } return x; };
    for (int i = 0; i < n; i++) for (int j = i + 1; j < n; j++) if (a[i][j]) { int x = f(i), y = f(j); if (x != y) { p[x] = y; comps--; } }
    return comps;
}
